    "patient_family_realworld_adaptation": "good"
  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00204",
          "explanation": "The doctor used reassuring, non-blaming language tailored to the caregiver’s anxiety and family pressure.",
          "quote": "延期不是您的错"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor repeatedly adapted Chinese explanations to an anxious caregiver, avoided both dismissiveness and catastrophizing, and used supportive framing that helped the caregiver continue the safety plan.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00121",
          "explanation": "The doctor made the plan executable in a busy ward by compressing it into a written script.",
          "quote": "医生来了照着念就行"
        }
      ],
      "completion": "complete",
      "explanation": "The caregiver’s fatigue, confusion, and limited bedside communication window were actively addressed with short scripts, paper notes, timing, and role-specific escalation steps.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00204",
          "explanation": "The doctor recognized the family conflict and caregiver blame dynamic, but did not fully ask about decision capacity, who would sign, or whether the patient personally heard the explanation.",
          "quote": "老人烦躁、怪您问多了"
        }
      ],
      "completion": "partial",
      "explanation": "The family-conflict trigger was visible and the doctor gave some non-blaming support, but the authored requirement to ask about the patient’s own capacity/true wishes and signing communication process was not fully completed.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": false,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00410",
          "explanation": "The doctor separated what could wait from what required active monitoring and follow-up.",
          "quote": "等病理、护伤口、观察麻木变化"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor safely carried forward allowed uncertainties about pathology, wound recovery, and numbness while defining what to monitor, when to call, and when to return for review.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
